const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || '').toString().trim();
const sessionId = (body.sessionId || 'session-' + Date.now()).toString();
const conversationId = (body.conversationId || body.sessionId || 'convo-' + Date.now()).toString();
const userId = (body.userId || 'anon-' + Date.now()).toString();
const userName = (body.userName || 'Creador').toString();
const role = (body.role === 'artist' || body.role === 'artista') ? 'artist' : 'client';
const page = (body.page || '/').toString();
const language = (body.language || 'es').toString();
const langNames = { es: 'Español', en: 'English', zh: '中文', fr: 'Français', it: 'Italiano', ja: '日本語' };
const languageName = langNames[language] || 'Español';

// Historial limitado a los últimos 10 mensajes
const rawHistory = Array.isArray(body.history) ? body.history : [];
const history = rawHistory.slice(-10).map((item) => ({
  role: item.role === 'assistant' || item.role === 'model' ? 'assistant' : 'user',
  content: (item.content || item.text || item.message || '').toString().slice(0, 1000)
}));

const preferences = Array.isArray(body.preferences)
  ? body.preferences.map(p => String(p)).slice(0, 10)
  : [];

const preferencesText = preferences.length > 0
  ? preferences.join(', ')
  : 'Arte digital en general';

// Filtrar tokens o datos sensibles
return [
  {
    json: {
      message,
      sessionId,
      conversationId,
      userId,
      userName,
      role,
      page,
      language,
      languageName,
      history,
      preferences,
      preferencesText,
      timestamp: new Date().toISOString()
    }
  }
];

