const input = $input.first().json || {};
const prev = $('Preparar Contexto').first().json || {};
const userMsg = (prev.message || '').toString();
const norm = userMsg.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const userRole = (prev.role || 'client').toString().toLowerCase();

// 1. Extraer salida textual del agente Gemini
let rawOutput = '';
if (typeof input.output === 'string' && input.output.trim()) {
  rawOutput = input.output;
} else if (input.output && typeof input.output.text === 'string' && input.output.text.trim()) {
  rawOutput = input.output.text;
} else if (typeof input.text === 'string' && input.text.trim()) {
  rawOutput = input.text;
} else if (typeof input.response === 'string' && input.response.trim()) {
  rawOutput = input.response;
} else if (typeof input.message === 'string' && input.message.trim()) {
  rawOutput = input.message;
} else if (typeof input === 'string' && input.trim()) {
  rawOutput = input;
}
rawOutput = (rawOutput || '').toString();

let intent = 'art_explanation';
let quickReplies = ['Explorar artistas', 'Cómo pedir comisión', 'Teoría del color'];
let actions = [{ type: 'open_explore', label: 'Explorar artistas' }];
let requiresConfirmation = false;

const ALLOWED_ACTIONS = ['open_artist_profile', 'open_commission', 'open_explore', 'open_requests', 'open_settings'];

let cleanMessage = rawOutput;

// Extraer bloque JSON opcional si viene al final
const jsonBlockMatch = rawOutput.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (jsonBlockMatch) {
  try {
    const parsed = JSON.parse(jsonBlockMatch[1].trim());
    if (parsed && typeof parsed === 'object') {
      if (typeof parsed.intent === 'string' && parsed.intent.trim()) intent = parsed.intent.trim();
      if (Array.isArray(parsed.quickReplies)) quickReplies = parsed.quickReplies.filter(r => typeof r === 'string' && r.trim().length > 0);
      if (Array.isArray(parsed.actions)) actions = parsed.actions.filter(a => a && typeof a === 'object' && ALLOWED_ACTIONS.includes(a.type));
      if (typeof parsed.requiresConfirmation === 'boolean') requiresConfirmation = parsed.requiresConfirmation;
      if (typeof parsed.message === 'string' && parsed.message.trim() && !cleanMessage.replace(/```(?:json)?[\s\S]*?```/g, '').trim()) {
        cleanMessage = parsed.message.trim();
      }
    }
  } catch (e) {}
}

// Quitar únicamente el bloque JSON si existía otro texto
if (cleanMessage !== rawOutput && cleanMessage) {
  // ya fue asignado desde parsed.message
} else {
  cleanMessage = cleanMessage.replace(/```(?:json)?\s*\{[\s\S]*?\}\s*```/g, '').trim();
}

// Si el mensaje estaba envuelto en bloques de código markdown generales, rescatar el texto
if (!cleanMessage && rawOutput) {
  cleanMessage = rawOutput.replace(/```[a-z]*\n?/gi, '').replace(/```/g, '').trim();
}

// Limpieza de etiquetas inseguras
cleanMessage = cleanMessage.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
cleanMessage = cleanMessage.replace(/<\/?[a-z][a-z0-9]*\b[^>]*>/gi, '');
cleanMessage = cleanMessage.trim();

// Si el resultado quedó vacío o Gemini reportó error (503, 429, timeout), resolver de forma útil y confiable
if (!cleanMessage || input.error || input.status === 'error' || input.name === 'Error') {
  if (norm.includes('acuarela') || norm.includes('watercolor')) {
    cleanMessage = 'La acuarela es una técnica pictórica sobre papel basada en pigmentos finamente molidos aglutinados con goma arábiga y solubles en agua. Su principal distinción es la transparencia y la luminosidad: la luz atraviesa las capas de color y se refleja en el blanco del papel, creando efectos radiantes que no se consiguen con medios opacos.\n\nAspectos fundamentales de la técnica:\n\n1. Control de agua y pigmento:\n   • Húmedo sobre húmedo (wet-on-wet): Se aplica pintura sobre papel previamente humedecido, generando degradados suaves, bordes difusos y atmósferas envolventes.\n   • Húmedo sobre seco (wet-on-dry): Se pinta sobre papel seco para trazar líneas definidas, detalles de primer plano y bordes limpios.\n\n2. El soporte y papel:\n   Es esencial utilizar papel específico de alto gramaje (300 g/m² o superior, 100% algodón o celulosa prensada) para que absorba el agua sin combarse ni romperse.\n\n3. Reserva de blancos y veladuras:\n   A diferencia de otras pinturas, no se usa pintura blanca para iluminar; las luces máximas se logran reservando el blanco original del papel o aplicando líquido enmascarador antes de pintar.\n\n4. Aplicación en ilustración digital:\n   En programas como Clip Studio Paint, Photoshop o Procreate, la acuarela se simula mediante pinceles con difusión de borde y modos de fusión de capa como "Multiplicar" para replicar la acumulación de veladuras transparentes.';
    intent = 'art_technique';
    quickReplies = ['Teoría del color', 'Técnica al óleo', 'Explorar artistas'];
  } else if (norm.includes('rol') || norm.includes('roles') || norm.includes('funcion') || norm.includes('funciones') || norm.includes('acceso') || norm.includes('permiso')) {
    if (userRole === 'artist' || userRole === 'artista') {
      cleanMessage = 'Como artista en ArtLink cuentas con un ecosistema completo para tu trabajo creativo:\n• Taller y Panel de Creador (/artista/panel): Control de encargos e ingresos asegurados.\n• Catálogo de Comisiones (/artista/comisiones): Configura tarifas, formatos y tiempos de entrega.\n• Portafolio (/artista/portafolio): Publica obras, modelados 3D y avatares VTuber.\n• Gestión de Solicitudes (/solicitudes): Revisa encargos entrantes y entrega por hitos.\n• Protección Escrow Shield: Fondos asegurados en custodia antes de comenzar la producción.\n• Rol Dual: Puedes cotizar o encargar piezas a otros creadores como cliente.';
    } else {
      cleanMessage = 'Como cliente en ArtLink tienes acceso a:\n• Explorar (/explorar): Filtra artistas por técnica, disciplina y presupuesto.\n• Cotizar Comisiones: Envía propuestas personalizadas protegidas con custodia Escrow Shield.\n• Gestión de Solicitudes (/solicitudes): Monitorea avances, aprueba hitos y descarga entregables.\n• Mensajería (/mensajes): Conversa directamente con tus artistas favoritos.';
    }
    intent = 'role_features';
  } else if (norm.includes('comision') || norm.includes('escrow') || norm.includes('cotizar') || norm.includes('seguridad')) {
    cleanMessage = 'El sistema de comisiones de ArtLink opera bajo el modelo de custodia protegida Escrow Shield:\n1. Propuesta: Envías tu encargo desde el perfil del artista con detalles y presupuesto acordado.\n2. Custodia de fondos: El dinero queda resguardado de forma segura en ArtLink.\n3. Entrega por hitos: El artista sube avances progresivos (boceto, entintado, color final).\n4. Liberación de pago: Los fondos solo se transfieren al artista cuando tú apruebas cada hito.';
    intent = 'explain_how_to_request';
  } else {
    cleanMessage = '¡Hola! Soy el asistente inteligente de ArtLink. Puedo ayudarte con:\n1. Funciones de ArtLink según tu rol (cliente, artista o administrador).\n2. Preguntas de arte (técnicas como acuarela, óleo, dibujo digital, modelado 3D, modelos VTuber, teoría del color e historia del arte).\n3. Navegación y comisiones protegidas con custodia Escrow Shield.\n\n¿Qué consulta deseas explorar hoy?';
    intent = 'art_explanation';
  }
}

const conversationId = (prev.conversationId || 'convo-default').toString();

return [
  {
    json: {
      success: true,
      message: cleanMessage,
      conversationId: conversationId,
      intent,
      quickReplies,
      actions,
      requiresConfirmation: Boolean(requiresConfirmation),
      provider: input.error ? 'artlink-knowledge' : 'gemini',
      model: 'gemini-3.1-flash-lite',
      timestamp: new Date().toISOString()
    }
  }
];
